use std::sync::{Arc, Mutex};use anyhow::Result;use axum::{    Router,    extract::State,    response::{Html, Json},    routing::{get, post},};use serde::{Deserialize, Serialize};use crate::client::ChatClient;use crate::config::{Config, Provider};use crate::conversation::Conversation;#[derive(Clone)]struct AppState {    session: Arc<Mutex<Option<ChatSession>>>,    conv: Arc<Mutex<Conversation>>,}#[derive(Clone)]struct ChatSession {    client: ChatClient,}#[derive(Deserialize)]struct ConnectRequest {    provider: String,    api_key: Option<String>,    model: String,    base_url: Option<String>,    system_prompt: Option<String>,    max_tokens: Option<u32>,}#[derive(Serialize)]struct ConnectResponse {    ok: bool,    provider: String,    model: String,    error: Option<String>,}#[derive(Deserialize)]struct ChatRequest {    message: String,}#[derive(Serialize)]struct ChatResponse {    reply: String,}async fn connect(    State(state): State<AppState>,    Json(req): Json<ConnectRequest>,) -> Json<ConnectResponse> {    let provider = match Provider::from_str(&req.provider) {        Ok(p) => p,        Err(e) => {            return Json(ConnectResponse {                ok: false,                provider: req.provider,                model: req.model,                error: Some(e.to_string()),            });        }    };    let api_key = req.api_key.unwrap_or_default();    if provider != Provider::Ollama && api_key.trim().is_empty() {        return Json(ConnectResponse {            ok: false,            provider: req.provider,            model: req.model,            error: Some("API key is required for OpenAI and Claude".to_string()),        });    }    let model = req.model.trim().to_string();    if model.is_empty() {        return Json(ConnectResponse {            ok: false,            provider: req.provider,            model,            error: Some("Model is required".to_string()),        });    }    let cfg = Config::from_runtime(        provider.clone(),        api_key,        model.clone(),        req.max_tokens.unwrap_or(1024),        req.system_prompt            .unwrap_or_else(|| "You are a helpful, concise assistant.".to_string()),        req.base_url,    );    let client = match ChatClient::new(cfg) {        Ok(c) => c,        Err(e) => {            return Json(ConnectResponse {                ok: false,                provider: req.provider,                model,                error: Some(e.to_string()),            });        }    };    {        let mut conv = state.conv.lock().unwrap();        *conv = Conversation::new();    }    {        let mut session = state.session.lock().unwrap();        *session = Some(ChatSession { client });    }    Json(ConnectResponse {        ok: true,        provider: provider.label().to_string(),        model,        error: None,    })}async fn chat(    State(state): State<AppState>,    Json(req): Json<ChatRequest>,) -> Json<ChatResponse> {    let session = {        let guard = state.session.lock().unwrap();        guard.clone()    };    let Some(session) = session else {        return Json(ChatResponse {            reply: "Error: Click Connect first and select a provider.".to_string(),        });    };    let messages = {        let mut conv = state.conv.lock().unwrap();        conv.add_user(&req.message);        conv.messages.clone()    };    match session.client.send(&messages).await {        Ok(reply) => {            let mut conv = state.conv.lock().unwrap();            conv.add_assistant(&reply);            Json(ChatResponse { reply })        }        Err(e) => {            let mut conv = state.conv.lock().unwrap();            conv.messages.pop();            Json(ChatResponse {                reply: format!("Error: {}", e),            })        }    }}async fn index() -> Html<&'static str> {    Html(HTML)}pub async fn start(port: u16) -> Result<()> {    let state = AppState {        session: Arc::new(Mutex::new(None)),        conv: Arc::new(Mutex::new(Conversation::new())),    };    let app = Router::new()        .route("/", get(index))        .route("/api/connect", post(connect))        .route("/api/chat", post(chat))        .with_state(state);    let addr = format!("0.0.0.0:{}", port);    println!("Web UI at http://localhost:{}/", port);    let listener = tokio::net::TcpListener::bind(&addr).await?;    axum::serve(listener, app).await?;    Ok(())}pub fn open_browser(port: u16) {    #[cfg(target_os = "windows")]    {        let _ = std::process::Command::new("cmd")            .args(["/C", "start", "", &format!("http://localhost:{}/", port)])            .spawn();    }}const HTML: &str = r#"<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Rust Chatbot</title><style>  * { margin: 0; padding: 0; box-sizing: border-box; }  body { font-family: "Segoe UI", sans-serif; background: linear-gradient(140deg, #0b1220, #111827); color: #e5e7eb; min-height: 100vh; display: flex; justify-content: center; padding: 16px; }  .app { width: min(960px, 100%); display: grid; grid-template-rows: auto 1fr auto; gap: 12px; }  .card { background: rgba(17, 24, 39, 0.9); border: 1px solid #374151; border-radius: 12px; padding: 12px; }  .row { display: grid; grid-template-columns: 180px 1fr 1fr; gap: 8px; margin-bottom: 8px; }  .row:last-child { margin-bottom: 0; }  label { font-size: 13px; color: #93c5fd; align-self: center; }  input, select { width: 100%; padding: 10px; border-radius: 8px; border: 1px solid #374151; background: #111827; color: #e5e7eb; }  button { padding: 10px 14px; border: 0; border-radius: 8px; cursor: pointer; color: white; background: #2563eb; }  button:hover { background: #1d4ed8; }  button:disabled { opacity: .6; cursor: not-allowed; }  #messages { min-height: 380px; max-height: 56vh; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; }  .msg { max-width: 80%; padding: 10px 12px; border-radius: 10px; line-height: 1.45; white-space: pre-wrap; }  .user { align-self: end; background: #2563eb; }  .assistant { align-self: start; background: #1f2937; }  .error { align-self: start; background: #3f1d1d; color: #fecaca; }  .status { font-size: 13px; color: #93c5fd; margin-top: 6px; }  .sendbar { display: grid; grid-template-columns: 1fr auto; gap: 8px; }  @media (max-width: 760px) {    .row { grid-template-columns: 1fr; }    label { margin-bottom: 4px; }  }</style></head><body>  <div class="app">    <div class="card">      <div class="row">        <label for="provider">Provider</label>        <select id="provider">          <option value="ollama">Ollama</option>          <option value="openai">OpenAI</option>          <option value="claude">Claude</option>        </select>        <button id="connect">Connect</button>      </div>      <div class="row">        <label for="apiKey">API Key</label>        <input id="apiKey" placeholder="Required for OpenAI/Claude">        <input id="model" placeholder="Model name">      </div>      <div class="row">        <label for="baseUrl">Base URL</label>        <input id="baseUrl" placeholder="Optional override">        <input id="systemPrompt" value="You are a helpful, concise assistant.">      </div>      <div id="status" class="status">Not connected</div>    </div>    <div id="messages" class="card"></div>    <div class="card sendbar">      <input id="input" type="text" placeholder="Type a message..." disabled>      <button id="send" disabled>Send</button>    </div>  </div><script>const provider = document.getElementById('provider');const apiKey = document.getElementById('apiKey');const model = document.getElementById('model');const baseUrl = document.getElementById('baseUrl');const systemPrompt = document.getElementById('systemPrompt');const statusEl = document.getElementById('status');const connectBtn = document.getElementById('connect');const messages = document.getElementById('messages');const input = document.getElementById('input');const send = document.getElementById('send');const defaults = {  ollama: { model: 'llama3.2', baseUrl: 'http://localhost:11434' },  openai: { model: 'gpt-4o', baseUrl: 'https://api.openai.com' },  claude: { model: 'claude-sonnet-4-20250514', baseUrl: 'https://api.anthropic.com' }};function syncDefaults() {  const d = defaults[provider.value];  model.value = d.model;  baseUrl.value = d.baseUrl;  if (provider.value === 'ollama') {    apiKey.value = '';    apiKey.disabled = true;  } else {    apiKey.disabled = false;  }}function addMsg(role, text) {  const div = document.createElement('div');  div.className = 'msg ' + role;  div.textContent = text;  messages.appendChild(div);  messages.scrollTop = messages.scrollHeight;}async function connect() {  connectBtn.disabled = true;  statusEl.textContent = 'Connecting...';  messages.innerHTML = '';  try {    const res = await fetch('/api/connect', {      method: 'POST',      headers: { 'Content-Type': 'application/json' },      body: JSON.stringify({        provider: provider.value,        api_key: apiKey.value.trim(),        model: model.value.trim(),        base_url: baseUrl.value.trim() || null,        system_prompt: systemPrompt.value.trim(),        max_tokens: 1024      })    });    const data = await res.json();    if (!data.ok) {      statusEl.textContent = data.error || 'Connection failed';      input.disabled = true;      send.disabled = true;      return;    }    statusEl.textContent = 'Connected: ' + data.provider + ' (' + data.model + ')';    input.disabled = false;    send.disabled = false;    input.focus();  } catch {    statusEl.textContent = 'Connection error';  } finally {    connectBtn.disabled = false;  }}async function sendMsg() {  const text = input.value.trim();  if (!text) return;  input.value = '';  addMsg('user', text);  send.disabled = true;  const loader = document.createElement('div');  loader.className = 'status';  loader.textContent = 'Assistant is thinking...';  messages.appendChild(loader);  try {    const res = await fetch('/api/chat', {      method: 'POST',      headers: { 'Content-Type': 'application/json' },      body: JSON.stringify({ message: text })    });    const data = await res.json();    loader.remove();    addMsg(data.reply.startsWith('Error:') ? 'error' : 'assistant', data.reply);  } catch {    loader.remove();    addMsg('error', 'Error: Network request failed');  } finally {    send.disabled = false;    input.focus();  }}provider.addEventListener('change', syncDefaults);connectBtn.addEventListener('click', connect);send.addEventListener('click', sendMsg);input.addEventListener('keydown', (e) => { if (e.key === 'Enter') sendMsg(); });syncDefaults();</script></body></html>"#;